p=Path('Notorious/Client/src/com/koios/client/arpg/ArtSprites.java');p.write_text('''package com.koios.client.arpg;
import java.awt.*;import java.awt.image.BufferedImage;import java.io.*;import java.util.*;import javax.imageio.ImageIO;import com.koios.client.graphic.Sprite;
/** Native atlas import: alpha-aware downsampling into the client's 32px item slots. */
public final class ArtSprites {
 private static final Map<Integer,Sprite> CACHE=new HashMap<>();private static final Map<String,BufferedImage> SHEETS=new HashMap<>();
 public static Sprite icon(int id){if(CACHE.containsKey(id))return CACHE.get(id);int tile,columns,rows;String file;int custom=CustomEquipment.index(id);if(id>=22400&&id<22407){file="currency-gems-v2.png";tile=id-22400;columns=rows=3;}else if(custom>=0&&custom<8){file="equipment-v2.png";tile=custom;columns=4;rows=2;}else if(custom>=8){file="currency-gems-v2.png";tile=custom-1;columns=rows=3;}else return null;
  try{BufferedImage atlas=SHEETS.get(file);if(atlas==null){File path=new File(System.getProperty("user.home"),"koios-cache/arpg-art/"+file);if(!path.isFile())path=new File("../koios-cache/arpg-art/"+file);atlas=ImageIO.read(path);if(atlas==null)throw new IOException("Unreadable atlas");SHEETS.put(file,atlas);}int col=tile%columns,row=tile/columns,left=col*atlas.getWidth()/columns,right=(col+1)*atlas.getWidth()/columns,top=row*atlas.getHeight()/rows,bottom=(row+1)*atlas.getHeight()/rows;BufferedImage cut=new BufferedImage(right-left,bottom-top,BufferedImage.TYPE_INT_ARGB);int minX=cut.getWidth(),minY=cut.getHeight(),maxX=-1,maxY=-1;for(int y=top;y<bottom;y++)for(int x=left;x<right;x++){int color=atlas.getRGB(x,y);if((color>>>24)<220)continue;int xx=x-left,yy=y-top;cut.setRGB(xx,yy,color);minX=Math.min(minX,xx);minY=Math.min(minY,yy);maxX=Math.max(maxX,xx);maxY=Math.max(maxY,yy);}if(maxX<0)throw new IOException("Empty atlas cell");int w=maxX-minX+1,h=maxY-minY+1;double scale=Math.min(30d/w,30d/h);int width=Math.max(1,(int)Math.round(w*scale)),height=Math.max(1,(int)Math.round(h*scale));BufferedImage output=new BufferedImage(32,32,BufferedImage.TYPE_INT_ARGB);Graphics2D graphics=output.createGraphics();graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BICUBIC);graphics.drawImage(cut,(32-width)/2,(32-height)/2,(32+width)/2,(32+height)/2,minX,minY,maxX+1,maxY+1,null);graphics.dispose();Sprite sprite=new Sprite(32,32);int[] rgba=output.getRGB(0,0,32,32,null,0,32);for(int i=0;i<rgba.length;i++)sprite.myPixels[i]=(rgba[i]>>>24)>=80?rgba[i]&0xFFFFFF:0;if(id>=22400&&id<22407){sprite.maxWidth=33;sprite.maxHeight=-1;}CACHE.put(id,sprite);return sprite;
  }catch(IOException ex){System.err.println("ARPG art load failed: "+file+" / "+ex.getMessage());CACHE.put(id,null);return null;}
 }
 public static Sprite outline(Sprite source,int color){if(source==null||color<=0)return source;Sprite copy=new Sprite(32,32);System.arraycopy(source.myPixels,0,copy.myPixels,0,1024);for(int y=0;y<32;y++)for(int x=0;x<32;x++)if(source.myPixels[x+y*32]==0&&(x>0&&source.myPixels[x-1+y*32]!=0||x<31&&source.myPixels[x+1+y*32]!=0||y>0&&source.myPixels[x+(y-1)*32]!=0||y<31&&source.myPixels[x+(y+1)*32]!=0))copy.myPixels[x+y*32]=color;copy.maxWidth=source.maxWidth;copy.maxHeight=source.maxHeight;return copy;}
}
''')
